window.MG_LAZY_DATA["data/lazy/resources/comm-v28-067-ec3f7dcaaf775f0b.json"]={sha256:"ec3f7dcaaf775f0b7e1b0b67fb970432796ba41ff4b37dd51987fb12c9ce4d8b",value:{"sources":[{"id":"v28-case-e2624336c5420a6c","url":"https://www.rfc-editor.org/rfc/rfc8639","title":"RFC 8639: Subscription to YANG Notifications","titleEn":"RFC 8639: Subscription to YANG Notifications","publisher":"RFC Editor / IETF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"comm-v28-067","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"comm-v28-067","related":[{"id":"comm-v28-068","referenceUrls":["https://www.rfc-editor.org/rfc/rfc5357"],"title":"TWAMP：往返時間與反射器駐留扣除","titleEn":"TWAMP: round-trip time and reflector residence","why":"用兩課的可觀察驗收條件比較模型邊界：第5項研究的可複查條件：接受48000/19200 B/s為均勻平均，需另估同時推送尖峰。 交接時須能核對：交付 subscription-events.csv、狀態時間圖與終止後靜默驗證。","whyEn":"Compare model boundaries using observable acceptance criteria: Investigation 5 review criterion: Accept48000/19200 B/s as uniform averages and estimate synchronized bursts separately. Handover must also reconcile: Deliver subscription-events.csv, state timelines and post-termination silence checks.","difference":"列四個時間戳t1送、t2收、t3返、t4到，sender與reflector各用本地差值。","differenceEn":"List t1 send, t2 receive, t3 reflect and t4 arrival, taking local differences at sender and reflector.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["訂閱式通知有建立、修改、終止及錯誤狀態；推送傳輸成功不代表應用已處理。\n教學基準：120/2*800 = 48000 B/s mean；對照：120/5*800 = 19200 B/s mean。所有數值、事件、期限與門檻是本課明示的合成教學情境，並非官方設備規格、營運網路量測或部署建議。","TWAMP可提供反射器收送時間；扣除駐留得到網路往返量仍不等於可拆成精確單向延遲。\n教學基準：30-4 = 26 ms network round trip；對照：30-9 = 21 ms network round trip。所有數值、事件、期限與門檻是本課明示的合成教學情境，並非官方設備規格、營運網路量測或部署建議。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Notification subscriptions have establish, modify, terminate and error states; transport delivery does not prove application processing.\nTeaching baseline: 120/2*800 = 48000 B/s mean; comparison: 120/5*800 = 19200 B/s mean. All numeric inputs, events, timers and limits are explicit synthetic teaching conditions, not official equipment specifications, operational-network measurements or deployment recommendations.","TWAMP reflector timestamps expose residence time; subtracting residence gives network round trip, not automatically exact one-way delays.\nTeaching baseline: 30-4 = 26 ms network round trip; comparison: 30-9 = 21 ms network round trip. All numeric inputs, events, timers and limits are explicit synthetic teaching conditions, not official equipment specifications, operational-network measurements or deployment recommendations.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"comm-v28-077","referenceUrls":["https://ocw.mit.edu/courses/6-450-principles-of-digital-communications-i-fall-2006/"],"title":"同步檢波 AM：載波功率與邊帶效率","titleEn":"Coherent AM reception: carrier power and sideband efficiency","why":"用兩課的可觀察驗收條件比較模型邊界：第5項研究的可複查條件：接受48000/19200 B/s為均勻平均，需另估同時推送尖峰。 交接時須能核對：交付 subscription-events.csv、狀態時間圖與終止後靜默驗證。","whyEn":"Compare model boundaries using observable acceptance criteria: Investigation 5 review criterion: Accept48000/19200 B/s as uniform averages and estimate synchronized bursts separately. Handover must also reconcile: Deliver subscription-events.csv, state timelines and post-termination silence checks.","difference":"能推導並解釋11.1111111111 %與33.3333333333 %，建立am_power.csv、載波/邊帶圖、包絡零交叉檢查，並完成以下驗收：效率增加不能支持m超過1；保留帶寬、包絡餘裕與接收方式的獨立限制。","differenceEn":"Derive and explain 11.1111111111 % and 33.3333333333 %; create am_power.csv, carrier/sideband diagram and envelope zero-crossing checks; apply this acceptance decision: Higher efficiency does not justify m>1; retain independent bandwidth, envelope-margin and receiver-type constraints.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["訂閱式通知有建立、修改、終止及錯誤狀態；推送傳輸成功不代表應用已處理。\n教學基準：120/2*800 = 48000 B/s mean；對照：120/5*800 = 19200 B/s mean。所有數值、事件、期限與門檻是本課明示的合成教學情境，並非官方設備規格、營運網路量測或部署建議。","從原理 單音傳統AM的兩邊帶合計功率為Pc*m²/2；總功率Pc*(1+m²/2)，效率m²/(2+m²)。 展開基準式 0.5**2/(2+0.5**2)*100；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：逐項列載波與兩邊帶功率1.25 W、5 W，再除總功率11.25 W、15 W；功率守恆。 將兩條推導一起存入 am_power.csv、載波/邊帶圖、包絡零交叉檢查。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Notification subscriptions have establish, modify, terminate and error states; transport delivery does not prove application processing.\nTeaching baseline: 120/2*800 = 48000 B/s mean; comparison: 120/5*800 = 19200 B/s mean. All numeric inputs, events, timers and limits are explicit synthetic teaching conditions, not official equipment specifications, operational-network measurements or deployment recommendations.","Starting from Single-tone conventional AM has total sideband power Pc*m²/2 and total power Pc*(1+m²/2), giving efficiency m²/(2+m²)., expand baseline expression 0.5**2/(2+0.5**2)*100; record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: List sideband totals1.25 W and5 W, then divide by total powers11.25 W and15 W; verify power conservation. Save both derivations with am_power.csv, carrier/sideband diagram and envelope zero-crossing checks.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v28-case-dbdfdc65afb852fe","url":"https://www.rfc-editor.org/rfc/rfc5357","title":"RFC 5357: A Two-Way Active Measurement Protocol (TWAMP)","titleEn":"RFC 5357: A Two-Way Active Measurement Protocol (TWAMP)","publisher":"RFC Editor / IETF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v28-case-12394b4a22706b67","url":"https://ocw.mit.edu/courses/6-450-principles-of-digital-communications-i-fall-2006/","title":"Principles of Digital Communications I","titleEn":"Principles of Digital Communications I","publisher":"MIT OpenCourseWare","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
